index 0037fca47eea..05b34a4eef68 100644
--- a/drivers/acpi/cppc_acpi.c
+++ b/drivers/acpi/cppc_acpi.c
@@ -2288,6 +2288,268 @@ int cppc_set_perf_limited(int cpu, u64 bits_to_clear)
 }
