+			    ((cpc)->type == ACPI_TYPE_BUFFER &&		\
+			     !IS_NULL_REG(&(cpc)->cpc_entry.reg)) ||	\
+			    ((cpc)->type == ACPI_TYPE_PACKAGE &&	\
+			     (cpc)->cpc_entry.package.count != 0))
 
